            "original_package_id TEXT", "variant_id TEXT NOT NULL DEFAULT ''", "product_id TEXT NOT NULL DEFAULT ''", "nozzle_min_c INTEGER", "nozzle_max_c INTEGER", "bed_min_c INTEGER", "bed_max_c INTEGER",
